mapper.sql:
AND ${alias}.business_date >= #{q.begin} AND ${alias}.business_date <= #{q.end}
AND ${alias}.store_id = #{q.storeId}
AND ${alias}.terminal_id = #{q.terminalId}
AND sh.cashier_id = #{q.cashierId}

mapper.select:
SELECT s.id AS sale_id, s.sale_no, s.kind, s.status, s.business_date, s.sale_time, st.name AS store_name, t.name AS terminal_name,
       u.nickname AS cashier_name, m.member_code, m.name AS member_name,
       mt.code AS material_code, mt.name AS material_name, mt.spec, i.unit,
       CASE WHEN s.kind = 'RETURN' THEN -i.input_qty ELSE i.input_qty END AS qty,
       i.list_price, i.sale_price,
       CASE WHEN s.kind = 'RETURN' THEN -i.amount ELSE i.amount END AS amount,
       CASE WHEN s.kind = 'RETURN' THEN -i.final_amount ELSE i.final_amount END AS final_amount,
       i.price_source
FROM pos_sale_item i
JOIN pos_sale s ON s.id = i.sale_id
JOIN wms_material mt ON mt.id = i.material_id
LEFT JOIN store_info st ON st.id = s.store_id
LEFT JOIN pos_terminal t ON t.id = s.terminal_id
LEFT JOIN sys_user u ON u.id = s.create_by
LEFT JOIN pos_member m ON m.id = s.member_id


        (s.sale_no LIKE CONCAT('%', #{q.keyword}, '%') OR mt.code LIKE CONCAT('%', #{q.keyword}, '%')
         OR mt.name LIKE CONCAT('%', #{q.keyword}, '%'))

    AND s.kind = #{q.kind}
    AND s.status = #{q.status}
    AND s.store_id = #{q.storeId}
    AND s.terminal_id = #{q.terminalId}
    AND s.create_by = #{q.cashierId}
    AND s.member_id = #{q.memberId}
    AND i.material_id = #{q.materialId}
    AND s.business_date >= #{q.begin}
    AND s.business_date <= #{q.end}

ORDER BY s.id DESC, i.line_no
